-- 
-- StoredProc PRC_CREAR_RECIBOS_FACTURA
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS PRC_CREAR_RECIBOS_FACTURA $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_RECIBOS_FACTURA`(IN `pSERIE_FACTURA` varchar(8),
	                                                                         IN `pNRO_FACTURA` int(8))
BEGIN
  DECLARE pCODIGO_FORMAPAGO VARCHAR(10);
	DECLARE pFORMA_PAGO_FACTURA VARCHAR(100);
	DECLARE pN_PLAZOS int(10); 
	DECLARE I int(10);
	DECLARE pDIAS_ENTRE_PLAZOS int(10);
	DECLARE pPORCEN_ANTICIPO decimal(5,2);
	DECLARE pCODIGO_CLIENTE  int(10);
	DECLARE pIBAN varchar(34);
	DECLARE pRAZONSOCIAL_CLIENTE varchar(200);
	DECLARE pDIRECCION1_CLIENTE  varchar(200);
	DECLARE pPOBLACION_CLIENTE  varchar(200);
	DECLARE pPROVINCIA_CLIENTE  varchar(200);
	DECLARE pCPOSTAL_CLIENTE  varchar(15);
	DECLARE pIMPORTE_LETRA  varchar(150);
	DECLARE pTOTAL_LIQUIDO_FACTURA decimal(18,6);
	DECLARE pIMPORTE_RECIBO decimal(18,6);
	DECLARE pIMPORTE_RESTO decimal(18,6);
	DECLARE pIMPORTE_ANTICIPO decimal(18,6);
	DECLARE pFECHA_VENCIMIENTO date;
	DECLARE pFECHA_FACTURA date;
	DECLARE finished INTEGER DEFAULT 0;
	DECLARE pTRATAMIENTO_LINEA VARCHAR(100);
  DECLARE pTRATAMIENTOS varchar(1000) DEFAULT '';
  DECLARE curTratamientos 
        CURSOR FOR 
            SELECT DESCRIPCION_ARTICULO_LINEA 
						  FROM suboc_facturas_lineas 
						 WHERE SERIE_FACTURA_LINEA = pSERIE_FACTURA 
						   AND NRO_FACTURA_LINEA = pNRO_FACTURA;
  DECLARE CONTINUE HANDLER 
        FOR NOT FOUND SET finished = 1;
	START TRANSACTION;
	DELETE FROM suboc_recibos 
   WHERE NRO_FACTURA = pNRO_FACTURA
	   AND SERIE_FACTURA = pSERIE_FACTURA;	
  OPEN curTratamientos;
  getTratamientos: LOOP
		FETCH curTratamientos INTO pTRATAMIENTO_LINEA;
		IF finished = 1 THEN 
				LEAVE getTratamientos;
		END IF;
		/* build email list */
		SET pTRATAMIENTOS = CONCAT(pTRATAMIENTOS,'\n',pTRATAMIENTO_LINEA);
  END LOOP getTratamientos;
	
	SELECT FORMA_PAGO_FACTURA, 
				 CODIGO_CLIENTE_FACTURA,
				 TOTAL_LIQUIDO_FACTURA,
				 RAZONSOCIAL_CLIENTE_FACTURA,
				 DIRECCION1_CLIENTE_FACTURA,
				 POBLACION_CLIENTE_FACTURA,
				 PROVINCIA_CLIENTE_FACTURA,
				 CPOSTAL_CLIENTE_FACTURA,
				 FECHA_FACTURA 
		INTO pFORMA_PAGO_FACTURA,
				 pCODIGO_CLIENTE,
				 pTOTAL_LIQUIDO_FACTURA,
				 pRAZONSOCIAL_CLIENTE,
				 pDIRECCION1_CLIENTE,
				 pPOBLACION_CLIENTE,
				 pPROVINCIA_CLIENTE,
				 pCPOSTAL_CLIENTE,
				 pFECHA_FACTURA
		FROM suboc_facturas
   WHERE SERIE_FACTURA = pSERIE_FACTURA
	   AND NRO_FACTURA = pNRO_FACTURA;
		 
		 SELECT IBAN 
		  INTO pIBAN
		 FROM suboc_clientes
		 WHERE CODIGO_CLIENTE = pCODIGO_CLIENTE;
		 
		 IF( EXISTS(
							 SELECT *
							 FROM suboc_formapago
							 WHERE DESCRIPCION_FORMAPAGO =  pFORMA_PAGO_FACTURA) ) THEN
		BEGIN
			SELECT CODIGO_FORMAPAGO, 
			       N_PLAZOS, 
						 DIAS_ENTRE_PLAZOS, 
						 PORCEN_ANTICIPO 
				INTO pCODIGO_FORMAPAGO,
				     pN_PLAZOS, 
						 pDIAS_ENTRE_PLAZOS,  
						 pPORCEN_ANTICIPO
				FROM suboc_formapago
				WHERE DESCRIPCION_FORMAPAGO = pFORMA_PAGO_FACTURA;
				
			IF ((pPORCEN_ANTICIPO = 100)) THEN
			BEGIN
				SELECT GET_NUMEROS_A_LETRAS(pTOTAL_LIQUIDO_FACTURA) 
			         INTO pIMPORTE_LETRA;		 
				INSERT INTO  suboc_recibos 
				       (NRO_FACTURA					         ,
								SERIE_FACTURA                ,
								NRO_PLAZO_RECIBO             ,
								FORMA_PAGO_ORIGEN            ,
								FORMA_PAGO_DESCRIPCION_ORIGEN,								
								EUROS_RECIBO                 ,
								ESTADO_RECIBO                ,
								FECHA_EXPEDICION             ,
								FECHA_VENCIMIENTO            ,
								IBAN                         ,
								FECHA_PAGO                   ,
								LOCALIDAD_EXPEDICION         ,
								CODIGO_CLIENTE               ,
								RAZONSOCIAL_CLIENTE          ,
								DIRECCION1_CLIENTE           ,
								POBLACION_CLIENTE            ,
								PROVINCIA_CLIENTE            ,
								CPOSTAL_CLIENTE              ,
								IMPORTE_LETRA                ,
							  TRATAMIENTOS	)
				VALUES( pNRO_FACTURA,
				        pSERIE_FACTURA,
								1,
								pCODIGO_FORMAPAGO,
								pFORMA_PAGO_FACTURA,
								pTOTAL_LIQUIDO_FACTURA,
								'Pagado',
								pFECHA_FACTURA,
								pFECHA_FACTURA,
								pIBAN,
								pFECHA_FACTURA,
								'Zamora',
								pCODIGO_CLIENTE,
								pRAZONSOCIAL_CLIENTE,
								pDIRECCION1_CLIENTE,
								pPOBLACION_CLIENTE,
								pPROVINCIA_CLIENTE,
								pCPOSTAL_CLIENTE,
								pIMPORTE_LETRA,
								pTRATAMIENTOS
							);
			END;
			ELSE 
			  IF (pN_PLAZOS >= 1) THEN
				BEGIN
			    SET I = 1;
					WHILE (I<=pN_PLAZOS) DO
					BEGIN
					      IF I = 1 THEN 
								BEGIN
								  SET pFECHA_VENCIMIENTO  = pFECHA_FACTURA;
								  SET pIMPORTE_ANTICIPO = pTOTAL_LIQUIDO_FACTURA * (pPORCEN_ANTICIPO/100);
									SET pIMPORTE_RESTO = (pTOTAL_LIQUIDO_FACTURA - pIMPORTE_ANTICIPO);
								  
								END;
								END IF;									
								IF ((I= 1) AND (pPORCEN_ANTICIPO > 0)) THEN								  
									SET pIMPORTE_RECIBO = pIMPORTE_ANTICIPO;
								ELSE
								  IF pN_PLAZOS > 1 THEN 
									  SET pIMPORTE_RECIBO = pIMPORTE_RESTO / (pN_PLAZOS - 1);
									ELSE
										SET pIMPORTE_RECIBO = pIMPORTE_RESTO;
									END IF;
								END IF;
							  SELECT GET_NUMEROS_A_LETRAS(pIMPORTE_RECIBO) 
     			        INTO pIMPORTE_LETRA;	
								IF (I <> 1) THEN
								  SET pFECHA_VENCIMIENTO = ADDDATE(pFECHA_VENCIMIENTO, INTERVAL pDIAS_ENTRE_PLAZOS DAY);
								END IF;
								
								INSERT INTO  suboc_recibos 
												 (NRO_FACTURA					         ,
													SERIE_FACTURA                ,
													NRO_PLAZO_RECIBO             ,
													FORMA_PAGO_ORIGEN            ,													
													FORMA_PAGO_DESCRIPCION_ORIGEN,
													EUROS_RECIBO                 ,
													ESTADO_RECIBO                ,
													FECHA_EXPEDICION             ,
													FECHA_VENCIMIENTO            ,
													IBAN                         ,
													FECHA_PAGO                   ,
													LOCALIDAD_EXPEDICION         ,
													CODIGO_CLIENTE               ,
													RAZONSOCIAL_CLIENTE          ,
													DIRECCION1_CLIENTE           ,
													POBLACION_CLIENTE            ,
													PROVINCIA_CLIENTE            ,
													CPOSTAL_CLIENTE              ,
													IMPORTE_LETRA                ,
													TRATAMIENTOS	)
								VALUES( pNRO_FACTURA,
													pSERIE_FACTURA,
													I,
													pCODIGO_FORMAPAGO,										
													pFORMA_PAGO_FACTURA,
													pIMPORTE_RECIBO,
													'Emitido',
													pFECHA_FACTURA,
													pFECHA_VENCIMIENTO,
													pIBAN,
													NULL,
													'Zamora',
													pCODIGO_CLIENTE,
													pRAZONSOCIAL_CLIENTE,
													pDIRECCION1_CLIENTE,
													pPOBLACION_CLIENTE,
													pPROVINCIA_CLIENTE,
													pCPOSTAL_CLIENTE,
													pIMPORTE_LETRA,
													pTRATAMIENTOS
												);
								SET I = I + 1;
					END;
					END WHILE;
				END;
				END IF;
			END IF;
		END;
		END IF;
		COMMIT;
END $$
DELIMITER ;


-- 
-- StoredProc PRC_CREAR_RECIBOS_PRESUPUESTO
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS PRC_CREAR_RECIBOS_PRESUPUESTO $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_CREAR_RECIBOS_PRESUPUESTO`(IN `pSERIE_FACTURA` varchar(8),
	                                                                         IN `pNRO_FACTURA` int(8))
BEGIN
  DECLARE pCODIGO_FORMAPAGO VARCHAR(10);
	DECLARE pFORMA_PAGO_FACTURA VARCHAR(100);
	DECLARE pN_PLAZOS int(10); 
	DECLARE I int(10);
	DECLARE pDIAS_ENTRE_PLAZOS int(10);
	DECLARE pPORCEN_ANTICIPO decimal(5,2);
	DECLARE pCODIGO_CLIENTE  int(10);
	DECLARE pIBAN varchar(34);
	DECLARE pRAZONSOCIAL_CLIENTE varchar(200);
	DECLARE pDIRECCION1_CLIENTE  varchar(200);
	DECLARE pPOBLACION_CLIENTE  varchar(200);
	DECLARE pPROVINCIA_CLIENTE  varchar(200);
	DECLARE pCPOSTAL_CLIENTE  varchar(15);
	DECLARE pIMPORTE_LETRA  varchar(150);
	DECLARE pTOTAL_LIQUIDO_FACTURA decimal(18,6);
	DECLARE pIMPORTE_RECIBO decimal(18,6);
	DECLARE pIMPORTE_RESTO decimal(18,6);
	DECLARE pIMPORTE_ANTICIPO decimal(18,6);
	DECLARE pFECHA_VENCIMIENTO date;
	DECLARE pFECHA_FACTURA date;
	DECLARE finished INTEGER DEFAULT 0;
	DECLARE pTRATAMIENTO_LINEA VARCHAR(100);
  DECLARE pTRATAMIENTOS varchar(1000) DEFAULT '';
  DECLARE curTratamientos 
        CURSOR FOR 
            SELECT DESCRIPCION_ARTICULO_LINEA 
						  FROM suboc_presupuestos_lineas 
						 WHERE SERIE_FACTURA_LINEA = pSERIE_FACTURA 
						   AND NRO_FACTURA_LINEA = pNRO_FACTURA;
  DECLARE CONTINUE HANDLER 
        FOR NOT FOUND SET finished = 1;
	START TRANSACTION;
	DELETE FROM suboc_recibos 
   WHERE NRO_FACTURA = pNRO_FACTURA
	   AND SERIE_FACTURA = pSERIE_FACTURA;	
  OPEN curTratamientos;
  getTratamientos: LOOP
		FETCH curTratamientos INTO pTRATAMIENTO_LINEA;
		IF finished = 1 THEN 
				LEAVE getTratamientos;
		END IF;
		/* build email list */
		SET pTRATAMIENTOS = CONCAT(pTRATAMIENTOS,'\n',pTRATAMIENTO_LINEA);
  END LOOP getTratamientos;
	
	SELECT FORMA_PAGO_FACTURA, 
				 CODIGO_CLIENTE_FACTURA,
				 TOTAL_LIQUIDO_FACTURA,
				 RAZONSOCIAL_CLIENTE_FACTURA,
				 DIRECCION1_CLIENTE_FACTURA,
				 POBLACION_CLIENTE_FACTURA,
				 PROVINCIA_CLIENTE_FACTURA,
				 CPOSTAL_CLIENTE_FACTURA,
				 FECHA_FACTURA 
		INTO pFORMA_PAGO_FACTURA,
				 pCODIGO_CLIENTE,
				 pTOTAL_LIQUIDO_FACTURA,
				 pRAZONSOCIAL_CLIENTE,
				 pDIRECCION1_CLIENTE,
				 pPOBLACION_CLIENTE,
				 pPROVINCIA_CLIENTE,
				 pCPOSTAL_CLIENTE,
				 pFECHA_FACTURA
		FROM suboc_presupuestos
   WHERE SERIE_FACTURA = pSERIE_FACTURA
	   AND NRO_FACTURA = pNRO_FACTURA;
		 
		 SELECT IBAN 
		  INTO pIBAN
		 FROM suboc_clientes
		 WHERE CODIGO_CLIENTE = pCODIGO_CLIENTE;
		 
		 IF( EXISTS(
							 SELECT *
							 FROM suboc_formapago
							 WHERE DESCRIPCION_FORMAPAGO =  pFORMA_PAGO_FACTURA) ) THEN
		BEGIN
			SELECT CODIGO_FORMAPAGO, 
			       N_PLAZOS, 
						 DIAS_ENTRE_PLAZOS, 
						 PORCEN_ANTICIPO 
				INTO pCODIGO_FORMAPAGO,
				     pN_PLAZOS, 
						 pDIAS_ENTRE_PLAZOS,  
						 pPORCEN_ANTICIPO
				FROM suboc_formapago
				WHERE DESCRIPCION_FORMAPAGO = pFORMA_PAGO_FACTURA;
				
			IF ((pPORCEN_ANTICIPO = 100)) THEN
			BEGIN
				SELECT GET_NUMEROS_A_LETRAS(pTOTAL_LIQUIDO_FACTURA) 
			         INTO pIMPORTE_LETRA;		 
				INSERT INTO  suboc_recibos 
				       (NRO_FACTURA					         ,
								SERIE_FACTURA                ,
								NRO_PLAZO_RECIBO             ,
								FORMA_PAGO_ORIGEN            ,
								FORMA_PAGO_DESCRIPCION_ORIGEN,								
								EUROS_RECIBO                 ,
								ESTADO_RECIBO                ,
								FECHA_EXPEDICION             ,
								FECHA_VENCIMIENTO            ,
								IBAN                         ,
								FECHA_PAGO                   ,
								LOCALIDAD_EXPEDICION         ,
								CODIGO_CLIENTE               ,
								RAZONSOCIAL_CLIENTE          ,
								DIRECCION1_CLIENTE           ,
								POBLACION_CLIENTE            ,
								PROVINCIA_CLIENTE            ,
								CPOSTAL_CLIENTE              ,
								IMPORTE_LETRA                ,
							  TRATAMIENTOS	)
				VALUES( pNRO_FACTURA,
				        pSERIE_FACTURA,
								1,
								pCODIGO_FORMAPAGO,
								pFORMA_PAGO_FACTURA,
								pTOTAL_LIQUIDO_FACTURA,
								'Pagado',
								pFECHA_FACTURA,
								pFECHA_FACTURA,
								pIBAN,
								pFECHA_FACTURA,
								'Zamora',
								pCODIGO_CLIENTE,
								pRAZONSOCIAL_CLIENTE,
								pDIRECCION1_CLIENTE,
								pPOBLACION_CLIENTE,
								pPROVINCIA_CLIENTE,
								pCPOSTAL_CLIENTE,
								pIMPORTE_LETRA,
								pTRATAMIENTOS
							);
			END;
			ELSE 
			  IF (pN_PLAZOS >= 1) THEN
				BEGIN
			    SET I = 1;
					WHILE (I<=pN_PLAZOS) DO
					BEGIN
					      IF I = 1 THEN 
								BEGIN
								  SET pFECHA_VENCIMIENTO  = pFECHA_FACTURA;
								  SET pIMPORTE_ANTICIPO = pTOTAL_LIQUIDO_FACTURA * (pPORCEN_ANTICIPO/100);
									SET pIMPORTE_RESTO = (pTOTAL_LIQUIDO_FACTURA - pIMPORTE_ANTICIPO);
								  
								END;
								END IF;									
								IF ((I= 1) AND (pPORCEN_ANTICIPO > 0)) THEN								  
									SET pIMPORTE_RECIBO = pIMPORTE_ANTICIPO;
								ELSE
								  IF pN_PLAZOS > 1 THEN 
									  SET pIMPORTE_RECIBO = pIMPORTE_RESTO / (pN_PLAZOS - 1);
									ELSE
										SET pIMPORTE_RECIBO = pIMPORTE_RESTO;
									END IF;
								END IF;
							  SELECT GET_NUMEROS_A_LETRAS(pIMPORTE_RECIBO) 
     			        INTO pIMPORTE_LETRA;	
								IF (I <> 1) THEN
								  SET pFECHA_VENCIMIENTO = ADDDATE(pFECHA_VENCIMIENTO, INTERVAL pDIAS_ENTRE_PLAZOS DAY);
								END IF;
								
								INSERT INTO  suboc_recibos 
												 (NRO_FACTURA					         ,
													SERIE_FACTURA                ,
													NRO_PLAZO_RECIBO             ,
													FORMA_PAGO_ORIGEN            ,													
													FORMA_PAGO_DESCRIPCION_ORIGEN,
													EUROS_RECIBO                 ,
													ESTADO_RECIBO                ,
													FECHA_EXPEDICION             ,
													FECHA_VENCIMIENTO            ,
													IBAN                         ,
													FECHA_PAGO                   ,
													LOCALIDAD_EXPEDICION         ,
													CODIGO_CLIENTE               ,
													RAZONSOCIAL_CLIENTE          ,
													DIRECCION1_CLIENTE           ,
													POBLACION_CLIENTE            ,
													PROVINCIA_CLIENTE            ,
													CPOSTAL_CLIENTE              ,
													IMPORTE_LETRA                ,
													TRATAMIENTOS	)
								VALUES( pNRO_FACTURA,
													pSERIE_FACTURA,
													I,
													pCODIGO_FORMAPAGO,										
													pFORMA_PAGO_FACTURA,
													pIMPORTE_RECIBO,
													'Emitido',
													pFECHA_FACTURA,
													pFECHA_VENCIMIENTO,
													pIBAN,
													NULL,
													'Zamora',
													pCODIGO_CLIENTE,
													pRAZONSOCIAL_CLIENTE,
													pDIRECCION1_CLIENTE,
													pPOBLACION_CLIENTE,
													pPROVINCIA_CLIENTE,
													pCPOSTAL_CLIENTE,
													pIMPORTE_LETRA,
													pTRATAMIENTOS
												);
								SET I = I + 1;
					END;
					END WHILE;
				END;
				END IF;
			END IF;
		END;
		END IF;
		COMMIT;
END $$
DELIMITER ;


-- 
-- StoredProc PRC_GET_DATA_ARTICULO
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS PRC_GET_DATA_ARTICULO $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_DATA_ARTICULO`(IN pidcodarticulo varchar(200), 
											OUT pidnomarticulo varchar(200), 
											OUT pidprecioventa decimal(18,6))
BEGIN
   IF( EXISTS(
             SELECT *
             FROM suboc_articulos
             WHERE `CODIGO_ARTICULO` =  pidcodarticulo) ) THEN
	BEGIN
	  SELECT DESCRIPCION_ARTICULO, PRECIOVENTA_ARTICULO 
      INTO pidnomarticulo, pidprecioventa	      
      FROM suboc_articulos
	   WHERE CODIGO_ARTICULO = pidcodarticulo;
	END;
	ELSE
	BEGIN
	  SET pidnomarticulo = '';
	  SET pidprecioventa = 0.00;
	END;
  END IF;
END $$
DELIMITER ;


-- 
-- StoredProc PRC_GET_EMPTY_FACTURA_PARA_VALIDAR
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS PRC_GET_EMPTY_FACTURA_PARA_VALIDAR $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_GET_EMPTY_FACTURA_PARA_VALIDAR`(IN `pNif` varchar(10),
    IN `pRazonSocial` varchar(200),
    OUT `pJsonResult` longtext)
BEGIN
    DECLARE vTotalFactura decimal(18,6);
    DECLARE vTotalIVA decimal(18,6);
    
    /* Calcular valores (simplificado) */
    SET vTotalIVA = 0;
    SET vTotalFactura = 0;
    
    /* Construir JSON básico */
    SET pJsonResult = JSON_OBJECT(
        'invoice', JSON_OBJECT(
            'id', JSON_OBJECT(
                'number', CONCAT(CONCAT('VALID_NIF_',pNIF) , '/', '1'),
                'issuedTime', DATE_FORMAT(CURRENT_DATE, '%Y-%m-%d')
            ),
            'type', 'F1',
            'description', JSON_OBJECT(
                'text', 'Factura de servicios odontológicos',
                'operationDate', DATE_FORMAT(CURRENT_DATE, '%Y-%m-%d')
            ),
            'recipient', JSON_OBJECT(
                'irsId', pNIF,
                'name', pRazonSocial,
                'country', 'ES'
            ),
            'vatLines', JSON_ARRAY(
                JSON_OBJECT(
                    'vatOperation', 'E1',
                    'base', 0,
                    'rate', 0,
                    'amount', 0,
                    'vatKey', '01'
                )
            ),
            'total', 0,
            'amount', 0
        )
    );
END $$
DELIMITER ;


-- 
-- StoredProc PRC_RESUMEN_ERRORES_VERIFACTU
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS PRC_RESUMEN_ERRORES_VERIFACTU $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `PRC_RESUMEN_ERRORES_VERIFACTU`()
BEGIN
    SELECT 
        'ERRORES DE VERIFACTU POR CÓDIGO' as TITULO,
        '' as SEPARADOR;
    
    SELECT 
        CODIGO_ERROR_VERIFACTU as CODIGO_ERROR,
        COUNT(*) as CANTIDAD_ERRORES,
        GROUP_CONCAT(DISTINCT CONCAT(SERIE_FACTURA, '/', NRO_FACTURA) SEPARATOR ', ') as FACTURAS_AFECTADAS,
        MAX(FECHA_PROCESAMIENTO) as ULTIMO_ERROR
    FROM suboc_verifactu_queue 
    WHERE CODIGO_ERROR_VERIFACTU IS NOT NULL
    GROUP BY CODIGO_ERROR_VERIFACTU
    ORDER BY CANTIDAD_ERRORES DESC;
    
    SELECT 
        'OPERACIONES CON QUEUE_ID DE VERIFACTU' as TITULO,
        '' as SEPARADOR;
        
    SELECT 
        COUNT(CASE WHEN VERIFACTU_QUEUE_ID IS NOT NULL THEN 1 END) as CON_QUEUE_ID,
        COUNT(CASE WHEN VERIFACTU_QUEUE_ID IS NULL THEN 1 END) as SIN_QUEUE_ID,
        COUNT(*) as TOTAL_OPERACIONES
    FROM suboc_verifactu_queue 
    WHERE ESTADO_COLA = 'COMPLETADO';
END $$
DELIMITER ;


-- 
-- StoredProc SET_CONSOLIDACION_FASE
-- 

DELIMITER $$
DROP PROCEDURE IF EXISTS SET_CONSOLIDACION_FASE $$
CREATE DEFINER=`root`@`localhost` PROCEDURE `SET_CONSOLIDACION_FASE`(IN pNumFactura int(8), 
                                           IN pSerieFactura varchar(8), 
                                           IN pFaseConso varchar(20), 
                                           IN pConso varchar(1))
BEGIN
  START TRANSACTION;
	 UPDATE suboc_facturas 
	    SET CONSOLIDACION_FACTURA = pConso,
          FASE_CONSOLIDACION_FACTURA = pFaseConso, 
          FECHA_ULT_CONSO_FACTURA = CURRENT_TIMESTAMP
	  WHERE NRO_FACTURA = pNumFactura 
      AND SERIE_FACTURA = pSerieFactura;
	COMMIT;
END $$
DELIMITER ;


