  `DESCRIPCION_LOG` text NOT NULL,
  `DATOS_ADICIONALES_LOG` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `HASH_ANTERIOR_LOG` char(64) NOT NULL,
  `HASH_PROPIO_LOG` char(64) NOT NULL,
  `FIRMA_DIGITAL_LOG` char(64) NOT NULL,
  `CREATED_AT_LOG` timestamp NULL DEFAULT current_timestamp(),
  `NRO_FACTURA_LOG` int(8) DEFAULT NULL,
  `SERIE_FACTURA_LOG` varchar(8) DEFAULT NULL,
  PRIMARY KEY (`ID_LOG`) USING BTREE,
  KEY `idx_timestamp` (`TIMESTAMP_LOG`) USING BTREE,
  KEY `idx_tipo_evento` (`TIPO_EVENTO_LOG`) USING BTREE,
  KEY `idx_usuario` (`USUARIO_LOG`) USING BTREE,
  KEY `idx_hash_propio` (`HASH_PROPIO_LOG`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2854 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci ROW_FORMAT=DYNAMIC;

