-- 
-- Table structure for table v_suboc_cola_pendientes_summary
-- 

DROP VIEW IF EXISTS v_suboc_cola_pendientes_summary;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_suboc_cola_pendientes_summary` AS select count(0) AS `TOTAL_PENDIENTES`,count(case when `suboc_verifactu_queue`.`FECHA_PROGRAMADA` <= current_timestamp() then 1 end) AS `READY_NOW`,count(case when `suboc_verifactu_queue`.`ESTADO_COLA` = 'PROCESANDO' then 1 end) AS `PROCESANDO`,count(case when `suboc_verifactu_queue`.`ESTADO_COLA` = 'ERROR' then 1 end) AS `CON_ERROR` from `suboc_verifactu_queue` where `suboc_verifactu_queue`.`ESTADO_COLA` in ('PENDIENTE','PROCESANDO','ERROR');

-- 
-- Table structure for table v_suboc_cola_verifactu
-- 

DROP VIEW IF EXISTS v_suboc_cola_verifactu;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_suboc_cola_verifactu` AS select `q`.`ID_QUEUE` AS `ID_QUEUE`,`q`.`TIPO_OPERACION` AS `TIPO_OPERACION`,`q`.`SERIE_FACTURA` AS `SERIE_FACTURA`,`q`.`NRO_FACTURA` AS `NRO_FACTURA`,`q`.`FECHA_PROGRAMADA` AS `FECHA_PROGRAMADA`,`q`.`FECHA_CREACION` AS `FECHA_CREACION`,`q`.`ESTADO_COLA` AS `ESTADO_COLA`,`q`.`INTENTOS` AS `INTENTOS`,`q`.`MAX_INTENTOS` AS `MAX_INTENTOS`,`q`.`PRIORIDAD` AS `PRIORIDAD`,`q`.`ERROR_MESSAGE` AS `ERROR_MESSAGE`,`q`.`FECHA_PROCESAMIENTO` AS `FECHA_PROCESAMIENTO`,`q`.`CREADO_POR` AS `CREADO_POR`,`q`.`NOTAS` AS `NOTAS`,`q`.`VERIFACTU_QUEUE_ID` AS `VERIFACTU_QUEUE_ID`,`q`.`VERIFACTU_REQUEST_ID` AS `VERIFACTU_REQUEST_ID`,`q`.`RESPUESTA_VERIFACTU` AS `RESPUESTA_VERIFACTU`,`q`.`CODIGO_ERROR_VERIFACTU` AS `CODIGO_ERROR_VERIFACTU`,`f`.`RAZONSOCIAL_CLIENTE_FACTURA` AS `RAZONSOCIAL_CLIENTE_FACTURA`,`f`.`TOTAL_LIQUIDO_FACTURA` AS `TOTAL_LIQUIDO_FACTURA`,`f`.`CONSOLIDACION_FACTURA` AS `CONSOLIDACION_FACTURA`,`f`.`FASE_CONSOLIDACION_FACTURA` AS `FASE_CONSOLIDACION_FACTURA`,case when `q`.`FECHA_PROGRAMADA` <= current_timestamp() then 'READY' else 'WAITING' end AS `STATUS_EJECUCION`,timestampdiff(SECOND,current_timestamp(),`q`.`FECHA_PROGRAMADA`) AS `SEGUNDOS_RESTANTES`,case `q`.`ESTADO_COLA` when 'PENDIENTE' then 1 when 'PROCESANDO' then 2 when 'COMPLETADO' then 3 when 'ERROR' then 4 when 'CANCELADO' then 5 else 6 end AS `ORDEN_ESTADO`,case when `q`.`CODIGO_ERROR_VERIFACTU` is not null then concat('ERROR VERIFACTU [',`q`.`CODIGO_ERROR_VERIFACTU`,']') when `q`.`ERROR_MESSAGE` is not null then concat('ERROR SISTEMA: ',left(`q`.`ERROR_MESSAGE`,50)) else 'SIN ERRORES' end AS `TIPO_ERROR` from (`suboc_verifactu_queue` `q` left join `suboc_facturas` `f` on(`q`.`SERIE_FACTURA` = `f`.`SERIE_FACTURA` and `q`.`NRO_FACTURA` = `f`.`NRO_FACTURA`)) order by `q`.`PRIORIDAD`,`q`.`FECHA_PROGRAMADA`;

