DROP VIEW IF EXISTS v_suboc_facturas;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_suboc_facturas` AS select `f`.`NRO_FACTURA` AS `NRO_FACTURA`,`f`.`SERIE_FACTURA` AS `SERIE_FACTURA`,`f`.`CODIGO_CLIENTE_FACTURA` AS `CODIGO_CLIENTE_FACTURA`,`f`.`RAZONSOCIAL_CLIENTE_FACTURA` AS `RAZONSOCIAL_CLIENTE_FACTURA`,`f`.`NIF_CLIENTE_FACTURA` AS `NIF_CLIENTE_FACTURA`,`f`.`MOVIL_CLIENTE_FACTURA` AS `MOVIL_CLIENTE_FACTURA`,`f`.`EMAIL_CLIENTE_FACTURA` AS `EMAIL_CLIENTE_FACTURA`,`f`.`DIRECCION1_CLIENTE_FACTURA` AS `DIRECCION1_CLIENTE_FACTURA`,`f`.`DIRECCION2_CLIENTE_FACTURA` AS `DIRECCION2_CLIENTE_FACTURA`,`f`.`POBLACION_CLIENTE_FACTURA` AS `POBLACION_CLIENTE_FACTURA`,`f`.`PROVINCIA_CLIENTE_FACTURA` AS `PROVINCIA_CLIENTE_FACTURA`,`f`.`CPOSTAL_CLIENTE_FACTURA` AS `CPOSTAL_CLIENTE_FACTURA`,`f`.`PAIS_CLIENTE_FACTURA` AS `PAIS_CLIENTE_FACTURA`,`f`.`TIPOID_INT_CLIENTE_FACTURA` AS `TIPOID_INT_CLIENTE_FACTURA`,`f`.`FECHA_FACTURA` AS `FECHA_FACTURA`,`f`.`TOTAL_LIQUIDO_FACTURA` AS `TOTAL_LIQUIDO_FACTURA`,`f`.`FORMA_PAGO_FACTURA` AS `FORMA_PAGO_FACTURA`,`f`.`COMENTARIOS_FACTURA` AS `COMENTARIOS_FACTURA`,`f`.`NOMBRE` AS `NOMBRE`,`f`.`APELLIDOS` AS `APELLIDOS`,`f`.`CONSOLIDACION_FACTURA` AS `CONSOLIDACION_FACTURA`,`c`.`REQUEST_ID` AS `REQUEST_ID`,`c`.`QUEUE_ID` AS `QUEUE_ID`,`c`.`ISSUER_IRS_ID` AS `ISSUER_IRS_ID`,`c`.`ISSUED_TIME` AS `ISSUED_TIME`,`c`.`CHAIN_NUMBER` AS `CHAIN_NUMBER`,`c`.`CHAIN_HASH` AS `CHAIN_HASH`,`c`.`VERIFACTU_URL` AS `VERIFACTU_URL`,`c`.`QRCODE_BASE64` AS `QRCODE_BASE64`,`c`.`QRCODE_PNG` AS `QRCODE_PNG`,`c`.`FECHA_PROCESAMIENTO` AS `FECHA_PROCESAMIENTO`,`c`.`ESTADO` AS `ESTADO`,`c`.`RESPUESTA_COMPLETA` AS `RESPUESTA_COMPLETA`,`c`.`PETICION_COMPLETA` AS `PETICION_COMPLETA`,`p`.`NOMBRE_SPA_PAIS` AS `NOMBRE_SPA_PAIS` from ((`suboc_facturas` `f` join `suboc_consolidacion` `c` on(`f`.`NRO_FACTURA` = `c`.`NRO_FACTURA` and `f`.`SERIE_FACTURA` = `c`.`SERIE_FACTURA`)) join `suboc_paises` `p` on(`f`.`PAIS_CLIENTE_FACTURA` = `p`.`COD_PAIS_ALPHA2`));

